xhtml:div.xhtml:script:
(function () {
  "use strict";
  var endpoint = "https://ubg-site.pages.dev/app.html";
  var baseUrl = "https://ubg-site.pages.dev/";
  var frame = document.getElementById("nero-app");
  var status = document.createElement("div");
  status.textContent = "Downloading NERO app.html…";
  status.style.cssText = "position:absolute;left:12px;bottom:12px;padding:8px 12px;background:#171717;color:#ddd;border:1px solid #333;border-radius:8px;font:12px Arial,sans-serif;z-index:10";
  document.body.appendChild(status);

  fetch(endpoint, {
    method: "GET",
    mode: "cors",
    credentials: "omit",
    cache: "no-store"
  }).then(function (response) {
    if (!response.ok) throw new Error("HTTP " + response.status);
    return response.text();
  }).then(function (html) {
    if (!html || !html.trim()) throw new Error("Empty app.html");
    var base = '<base href="' + baseUrl + '">';
    if (/<head(?:\\s[^>]*)?>/i.test(html)) {
      html = html.replace(/<head(?:\\s[^>]*)?>/i, function (tag) {
        return tag + base;
      });
    } else {
      html = '<!doctype html><html><head>' + base +
        '</head><body>' + html + '</body></html>';
    }
    frame.srcdoc = html;
    status.textContent = "app.html downloaded and injected";
    setTimeout(function () { status.remove(); }, 4000);
  }).catch(function (error) {
    status.textContent = "Could not download app.html: " +
      (error && error.message ? error.message : "fetch blocked");
  });
})();
